const URL_RE = /^https?:\/\/[^\s\/$.?#][^\s]*$/i;
const LINKEDIN_RE = /^https?:\/\/([a-z]{2,3}\.)?(www\.)?linkedin\.com\/company\/[^\/\s?#]+\/?([?#].*)?$/i;

const isUrl = (s) => URL_RE.test(s);
const isLinkedInCompany = (s) => LINKEDIN_RE.test(s);
const show = (v) => '"' + String(v).slice(0, 60) + '"';

const seen = new Set();
const results = [];

for (const item of $input.all()) {
  const r = item.json;
  const errors = [];
  const warnings = [];

  const company = String(r.company || '').trim();
  const active = String(r.active || '').trim().toUpperCase() === 'TRUE';

  if (!active) { results.push({ json: { status: 'skipped_inactive', company } }); continue; }

  if (!company) errors.push('company is required');
  else if (seen.has(company.toLowerCase())) errors.push('duplicate company');

  const linkedin = String(r.linkedin_url || '').trim();
  if (!isLinkedInCompany(linkedin)) errors.push('invalid linkedin_url: ' + show(linkedin));

  const website = String(r.website_url || '').trim();
  if (!website) errors.push('website_url is required');
  else if (!isUrl(website)) errors.push('invalid website_url: ' + show(website));

  const newsroom = String(r.newsroom_or_rss_url || '').trim();
  if (newsroom && !isUrl(newsroom)) errors.push('invalid newsroom_or_rss_url: ' + show(newsroom));
  if (!newsroom) warnings.push('no newsroom_or_rss_url (website scrape will be less reliable)');

  if (errors.length) {
    results.push({ json: { status: 'rejected', company, errors, warnings } });
    continue;
  }

  seen.add(company.toLowerCase());
  const aliases = String(r.aliases || '').split(';').map(a => a.trim()).filter(Boolean);
  results.push({ json: {
    status: 'valid', company, aliases,
    linkedin_url: linkedin, website_url: website,
    newsroom_or_rss_url: newsroom, warnings
  } });
}
return results;

const norm = (u) => String(u || '').toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/[?#].*$/, '').replace(/\/+$/, '');
const byUrl = {};
for (const c of $('Keep Valid Only').all()) byUrl[norm(c.json.linkedin_url)] = c.json.company;
const clean = (t) => String(t || '').replace(/\r/g, '').replace(/[ \t\u00a0]+/g, ' ').replace(/ ?\n ?/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const stripQuery = (u) => String(u || '').replace(/[?#].*$/, '');
const collectedAt = new Date().toISOString();
const out = [];
for (const item of $input.all()) {
  const p = item.json;
  if (p.error) { out.push({ json: { status: 'rejected', source: 'linkedin', errors: ['apify error: ' + String(p.error).slice(0, 200)] } }); continue; }
  const errors = [];
  const company = byUrl[norm(p.query && p.query.targetUrl)];
  if (!company) errors.push('unknown company (query.targetUrl not found in sheet)');
  if (!p.id) errors.push('missing post id');
  if (!p.linkedinUrl) errors.push('missing post url');
  const published = p.postedAt && p.postedAt.date;
  if (!published || isNaN(Date.parse(published))) errors.push('invalid published date');
  const text = clean(p.content);
  const images = (p.postImages || []).map(i => i.url).filter(Boolean);
  const article = p.article ? { title: clean(p.article.title), link: stripQuery(p.article.link) } : null;
  if (!text && !article && !images.length) errors.push('empty post');
  if (errors.length) { out.push({ json: { status: 'rejected', source: 'linkedin', id: p.id || null, company: company || null, errors } }); continue; }
  const e = p.engagement || {};
  out.push({ json: {
    status: 'ok',
    id: 'linkedin_' + p.id,
    company,
    source: 'linkedin',
    url: stripQuery(p.linkedinUrl),
    published_at: new Date(published).toISOString(),
    age_days: Math.round((Date.now() - Date.parse(published)) / 8640000) / 10,
    text,
    image_urls: images,
    engagement: { likes: e.likes || 0, comments: e.comments || 0, shares: e.shares || 0 },
    article,
    mentioned_companies: (p.contentAttributes || []).filter(a => a.type === 'COMPANY_NAME' && a.company).map(a => a.company.name),
    collected_at: collectedAt
  } });
}
return out;

const WINDOW_DAYS = 7; // set to 7 for production
const DROP_AT = 0.8;
const FLAG_AT = 0.25;
const MIN_TEXT = 20;
const STOP = new Set('the a an and or of to in at for with on is are we our it its this that by as be from you your'.split(' '));
const tokens = (t) => {
  const w = String(t || '').toLowerCase().replace(/https?:\/\/\S+/g, ' ').match(/[a-z0-9]+/g) || [];
  return new Set(w.filter(x => x.length > 1 && !STOP.has(x)));
};
const jaccard = (A, B) => {
  if (!A.size || !B.size) return 0;
  let n = 0;
  for (const x of A) if (B.has(x)) n++;
  return n / (A.size + B.size - n);
};
const normUrl = (u) => String(u || '').toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/[?#].*$/, '').replace(/\/+$/, '');

const all = $input.all().map(i => i.json);
const out = [];
const cutoff = Date.now() - WINDOW_DAYS * 86400000;
const ok = [];

for (const p of all) {
  if (p.status !== 'ok') { out.push({ ...p, filter_status: 'dropped', filter_reason: 'rejected at normalize' }); continue; }
  if (Date.parse(p.published_at) < cutoff) { out.push({ ...p, filter_status: 'dropped', filter_reason: 'older than ' + WINDOW_DAYS + ' days' }); continue; }
  if ((p.text || '').length < MIN_TEXT && !p.article) { out.push({ ...p, filter_status: 'dropped', filter_reason: 'too little text' }); continue; }
  ok.push(p);
}

ok.sort((a, b) => Date.parse(a.published_at) - Date.parse(b.published_at));
const seenIds = new Set();
const seenUrls = new Set();
const keptByCompany = {};

for (const p of ok) {
  const u = normUrl(p.url);
  if (seenIds.has(p.id) || seenUrls.has(u)) { out.push({ ...p, filter_status: 'dropped', filter_reason: 'exact duplicate (same id or url)' }); continue; }
  seenIds.add(p.id);
  seenUrls.add(u);
  const tk = tokens((p.text || '') + ' ' + (p.article ? p.article.title : ''));
  const kept = keptByCompany[p.company] = keptByCompany[p.company] || [];
  let best = { id: null, sim: 0 };
  for (const k of kept) { const s = jaccard(tk, k.tk); if (s > best.sim) best = { id: k.id, sim: s }; }
  if (best.sim >= DROP_AT) { out.push({ ...p, filter_status: 'dropped', filter_reason: 'near-duplicate of ' + best.id + ' (' + best.sim.toFixed(2) + ')' }); continue; }
  const item = { ...p, filter_status: 'keep', filter_reason: '' };
  if (best.sim >= FLAG_AT) { item.possible_duplicate_of = best.id; item.similarity = Math.round(best.sim * 100) / 100; }
  kept.push({ id: p.id, tk });
  out.push(item);
}

return out.map(j => ({ json: j }));

