// ===== CONFIG (edit here) =====
const MAX_AGE_DAYS = 30;           // Strict 30-day cutoff for time-sensitive pages only
const MAX_PER_CATEGORY = 10;       // Max links kept per category (0 = no cap)
const MAX_LINKS_PER_RUN = 30;      // Safety cap for scrape credits per competitor run
const INCLUDE_WEBINARS = false;

const COMPANY_SOURCE_NODE = 'Loop Over Competitors';
const EXTRA_DOMAINS = [];

const hostOf = (u) => { 
  const m = String(u || '').match(/^https?:\/\/([^\/?#]+)/i); 
  return m ? m[1].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, '') : ''; 
};

// 1. Build authoritative domain-to-company registry
const COMPANY_BY_DOMAIN = {};
const allCompetitors = (() => {
  try { return $('Keep Valid Only').all().map(i => i.json); } catch (e) {}
  try { return $('Validate Companies1').all().map(i => i.json); } catch (e) {}
  try { return $(COMPANY_SOURCE_NODE).all().map(i => i.json); } catch (e) {}
  return [];
})();

for (const c of allCompetitors) {
  if (!c || !c.company) continue;
  [hostOf(c.website_url), hostOf(c.listing_url)]
    .filter(Boolean)
    .forEach(d => { COMPANY_BY_DOMAIN[d] = c.company; });
}

let current = {};
try { current = $(COMPANY_SOURCE_NODE).item.json || {}; } catch (e) {}
if (!current.company) {
  try { current = $('Website Targets').item.json || {}; } catch (e) {}
}
if (!current.company) {
  const firstIn = $input.first()?.json || {};
  if (firstIn.company) current = firstIn;
}

if (current.company) {
  [hostOf(current.website_url), hostOf(current.listing_url), ...EXTRA_DOMAINS.map(d => String(d).toLowerCase())]
    .filter(Boolean)
    .forEach(d => { COMPANY_BY_DOMAIN[d] = current.company; });
}

if (!Object.keys(COMPANY_BY_DOMAIN).length) {
  throw new Error('No company found. Looked in "' + COMPANY_SOURCE_NODE + '" and incoming items.');
}

const FOCUS = {
  'Product & Features': 'Core offerings, value propositions, key capabilities, target industries, and tech ecosystem compatibility.',
  'Pricing & Plans': 'Unit pricing, feature gating across tiers, discounting strategies, freemium boundaries, and add-on costs.',
  'Content & Strategy': 'Keyword targeting, content focus areas, customer success stories, client logos, and sales positioning.',
  'Company & Hiring': 'Strategic focus (via job openings), team size/growth, company mission, and geographic expansion.',
  'Support & Tech Docs': 'Product depth, technical architecture, API capabilities, and product update cadence.',
  'News & Events': 'Product launches, partnerships, company announcements, and event participation.'
};

const RULES = [
  { cat: 'webinar',      section: 'Content & Strategy',  re: /\/webinars?(\/|$)/, slug: true, optional: true, timeSensitive: true },
  { cat: 'press',        section: 'News & Events',       re: /\/(press|press-releases?|newsroom|news-and-pr|news-and-media|newscenter|media-center|news)(\/|$)/, slug: true, timeSensitive: true },
  { cat: 'events',       section: 'News & Events',       re: /\/events(-webinars)?(\/|$)/, slug: false, timeSensitive: true },
  { cat: 'case_study',   section: 'Content & Strategy',  re: /\/(case-studies|customer-stories|success-stories|customer-success)(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'customers',    section: 'Content & Strategy',  re: /\/customers?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'blog',         section: 'Content & Strategy',  re: /\/blog(\/|$)/, slug: true, timeSensitive: true },
  { cat: 'resources',    section: 'Content & Strategy',  re: /\/resources?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'pricing',      section: 'Pricing & Plans',     re: /\/(pricing|plans?|billing-faq|enterprise)(\/|$)/, slug: false, timeSensitive: false },
  { cat: 'products',     section: 'Product & Features',  re: /\/products?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'features',     section: 'Product & Features',  re: /\/features?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'solutions',    section: 'Product & Features',  re: /\/solutions?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'integrations', section: 'Product & Features',  re: /\/integrations?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'partners',     section: 'Content & Strategy',  re: /\/partners?(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'changelog',    section: 'Support & Tech Docs', re: /\/(changelog|release-notes)(\/|$)/, slug: false, timeSensitive: true },
  { cat: 'docs',         section: 'Support & Tech Docs', re: /\/(docs?|documentation)(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'help',         section: 'Support & Tech Docs', re: /\/help(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'api',          section: 'Support & Tech Docs', re: /\/api(\/|$)/, slug: true, timeSensitive: false },
  { cat: 'careers',      section: 'Company & Hiring',    re: /\/(careers?|jobs?)(\/|$)/, slug: false, timeSensitive: false },
  { cat: 'team',         section: 'Company & Hiring',    re: /\/team(\/|$)/, slug: false, timeSensitive: false },
  { cat: 'about',        section: 'Company & Hiring',    re: /\/(about|about-us)(\/|$)/, slug: false, timeSensitive: false }
];

const EXCLUDE = [
  /\.(pdf|jpe?g|png|gif|svg|webp|zip|xml|json|css|js|mp4|docx?|xlsx?|pptx?)$/,
  /\/wp-(content|json|admin|includes)\//,
  /\/(terms|terms-conditions|privacy|privacy-policy|legal|compliance|compliance-policies|company-notices|accessibility|cookie)/,
  /\/(my-account|login|signin|register|cart|checkout|where-to-buy|contact|contact-us|subscribe|newsletter-subscription|search|sitemap)(\/|$)/,
  /\/(tag|category|author|feed)(\/|$)/,
  /\/page\/\d+/
];

const parse = (u) => {
  const m = String(u || '').trim().match(/^(https?):\/\/([^\/?#]+)([^?#]*)/i);
  if (!m) return null;
  return { host: m[2].toLowerCase().replace(/^www\./, '').replace(/:\d+$/, ''), path: (m[3] || '/').toLowerCase() };
};

const companyOf = (host) => {
  for (const d of Object.keys(COMPANY_BY_DOMAIN)) {
    if (host === d || host.endsWith('.' + d)) return COMPANY_BY_DOMAIN[d];
  }
  return current.company || null;
};

// Strict cutoff: MAX_AGE_DAYS ago
const now = Date.now();
const cutoffTime = now - (MAX_AGE_DAYS * 86400000);
const OLD_YEAR_BEFORE = new Date(cutoffTime).getUTCFullYear();

// Date detection helper
const detectDate = (text) => {
  if (!text) return null;
  // Format: YYYY/MM/DD or YYYY-MM-DD
  let m = text.match(/(?:^|[^a-z0-9])(20\d\d)[\/-](0[1-9]|1[0-2])[\/-](0[1-9]|[12]\d|3[01])(?!\d)/i);
  if (m) return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3]));

  // Format: YYYY/MM or YYYY-MM
  m = text.match(/(?:^|[^a-z0-9])(20\d\d)[\/-](0[1-9]|1[0-2])(?!\d)/i);
  if (m) return new Date(Date.UTC(+m[1], +m[2], 0));

  // Format: Month DD, YYYY
  m = text.match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s+(\d{1,2}),?\s+(20\d\d)\b/i);
  if (m) {
    const months = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };
    return new Date(Date.UTC(+m[3], months[m[1].slice(0,3).toLowerCase()], +m[2]));
  }

  // Format: Standalone Year older than cutoff year
  m = text.match(/(?:^|[^a-z0-9])(20\d\d)(?!\d)/);
  if (m && +m[1] < OLD_YEAR_BEFORE) return new Date(Date.UTC(+m[1], 11, 31));

  return null;
};

// Extract links from inputs
const rows = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (Array.isArray(j.links)) j.links.forEach(l => rows.push(typeof l === 'string' ? { url: l } : l));
  else if (j.links && typeof j.links === 'object') rows.push({ ...j.links, success: j.success });
  else if (typeof j.links === 'string') rows.push({ url: j.links });
  else if (j.url) rows.push(j);
}

const seen = new Set();
const counts = {};
const cands = [];
const out = [];
const drop = (r, reason, company) => out.push({ json: { link_status: 'drop', link_reason: reason, company: company || null, url: r.url || null, title: r.title || '' } });

for (const r of rows) {
  const url = String(r.url || '').trim();
  const p = parse(url);
  if (!p) { drop({ url }, 'invalid url'); continue; }
  const company = companyOf(p.host);

  const key = (p.host + p.path).replace(/\/index\.(html?|php)$/, '').replace(/\/+$/, '');
  if (r.success === false) { drop(r, 'map item not successful', company); continue; }
  if (seen.has(key)) { drop(r, 'duplicate url', company); continue; }
  seen.add(key);
  if (EXCLUDE.some(re => re.test(p.path))) { drop(r, 'excluded (file, legal, account or utility page)', company); continue; }

  let rule = null;
  let indexOnly = false;
  for (const c of RULES) {
    const m = p.path.match(c.re);
    if (!m) continue;
    const rest = p.path.slice(m.index + m[0].length);
    if (c.slug && rest.replace(/\//g, '').length < 2) { indexOnly = true; break; }
    rule = c;
    break;
  }
  if (!rule) {
    const sub = p.host.split('.')[0];
    if (/^(blog|news|press|newsroom)$/.test(sub) && p.path.replace(/\//g, '').length >= 2) {
      rule = { cat: sub === 'blog' ? 'blog' : 'press', section: sub === 'blog' ? 'Content & Strategy' : 'News & Events', timeSensitive: true };
    }
  }
  if (!rule) { drop(r, indexOnly ? 'section index page (no article)' : 'not in keep list', company); continue; }
  if (rule.optional && !INCLUDE_WEBINARS) { drop(r, 'webinars disabled', company); continue; }

  // Date rules apply ONLY to time-sensitive pages (blog, press, events, changelog, webinar).
  // Evergreen pages (products, solutions, team, careers, docs) are NOT dropped for missing or older dates!
  let detectedDate = null;
  if (rule.timeSensitive) {
    detectedDate = detectDate(p.path) || detectDate(r.title) || detectDate(r.description);

    if (detectedDate && detectedDate.getTime() < cutoffTime) {
      drop(r, `old date detected (${detectedDate.toISOString().slice(0,10)} < ${MAX_AGE_DAYS} days cutoff)`, company);
      continue;
    }

    // Check if an older year exists in the URL path (ONLY for time-sensitive news/press/blogs)
    const yearMatches = p.path.match(/(?:^|[^a-z0-9])(20\d\d)(?!\d)/g);
    if (yearMatches) {
      const hasOldYear = yearMatches.some(y => {
        const yr = parseInt(y.replace(/[^0-9]/g, ''), 10);
        return yr < OLD_YEAR_BEFORE;
      });
      if (hasOldYear) {
        drop(r, 'older year found in url path', company);
        continue;
      }
    }
  }

  if (!company) { drop(r, 'domain not in COMPANY_BY_DOMAIN', company); continue; }

  cands.push({ detectedDate, rule, company, r, url });
}

// Sort newest detected dates first (undated evergreen pages remain stable)
const sortKey = (c) => (c.detectedDate ? c.detectedDate.getTime() : 0);
cands.sort((a, b) => sortKey(b) - sortKey(a));

let total = 0;
for (const c of cands) {
  const ck = c.company + '|' + c.rule.cat;
  const n = (counts[ck] || 0) + 1;
  if (MAX_PER_CATEGORY > 0 && n > MAX_PER_CATEGORY) { drop(c.r, 'over cap (' + MAX_PER_CATEGORY + ' per category)', c.company); continue; }
  if (MAX_LINKS_PER_RUN > 0 && total >= MAX_LINKS_PER_RUN) { drop(c.r, 'over run cap (' + MAX_LINKS_PER_RUN + ' links)', c.company); continue; }
  counts[ck] = n;
  total++;
  out.push({ 
    json: {
      link_status: 'keep', 
      link_reason: c.rule.section + ' / ' + c.rule.cat,
      company: c.company, 
      section: c.rule.section, 
      category: c.rule.cat,
      time_sensitive: !!c.rule.timeSensitive,
      extract_focus: FOCUS[c.rule.section],
      url_date: c.detectedDate ? c.detectedDate.toISOString().slice(0, 10) : null,
      url: c.url.replace(/[?#].*$/, ''), 
      title: c.r.title || '', 
      description: c.r.description || ''
    } 
  });
}

return out;

// ===== CONFIGURATION =====
const MAX_CHAR_LENGTH = 3000;        // Hard character ceiling per page to protect LLM context
const MIN_BODY_LENGTH = 100;         // Drop pages that have no real content after cleaning
const MAX_AGE_DAYS = 30;             // Time-sensitive pages older than this are dropped
const NEAR_DUP_THRESHOLD = 0.85;     // Jaccard similarity at/above which two pages (same company) are duplicates
const RESET_AFTER_MS = 60 * 60 * 1000; // Dedupe memory is cleared if idle this long (= a new run)

const TIME_SENSITIVE_PATH = /\/(blog|news|press|press-releases?|newsroom|events|changelog|release-notes|webinars?)(\/|$)/;
const STOP = new Set('the a an and or of to in at for with on is are we our it its this that by as be from you your was were has have will can not but they their more also into than then which who'.split(' '));
const MONTHS = { jan:0, feb:1, mar:2, apr:3, may:4, jun:5, jul:6, aug:7, sep:8, oct:9, nov:10, dec:11 };

// ===== HELPERS =====
const norm = (u) => String(u || '').toLowerCase()
  .replace(/^https?:\/\/(www\.)?/, '')
  .replace(/[?#].*$/, '')
  .replace(/\/index\.(html?|php)$/, '')
  .replace(/\/+$/, '');

const toIso = (v) => {
  if (!v) return null;
  const t = Date.parse(v);
  return isNaN(t) ? null : new Date(t).toISOString();
};

// 53-bit hash (far fewer collisions than a 32-bit hash)
const cyrb53 = (str, seed = 0) => {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0, ch; i < str.length; i++) {
    ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return 4294967296 * (2097151 & h2) + (h1 >>> 0);
};

// Text fingerprint: lowercase letters/digits only, single spaces
const fingerprintText = (t) => String(t || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// Unique meaningful words (used for near-duplicate detection)
const tokensOf = (t) => {
  const words = fingerprintText(t).split(' ');
  const set = new Set();
  for (const w of words) {
    if (w.length > 2 && !STOP.has(w)) set.add(w);
    if (set.size >= 500) break;
  }
  return Array.from(set);
};

const jaccard = (arrA, arrB) => {
  if (!arrA.length || !arrB.length) return 0;
  const B = new Set(arrB);
  let n = 0;
  for (const x of arrA) if (B.has(x)) n++;
  return n / (arrA.length + B.size - n);
};

// Date written inside the page text, e.g. "November 18, 2025" or "Nov. 18, 2025"
const dateFromText = (t) => {
  const m = String(t || '').match(/\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\.?\s+(\d{1,2}),?\s+(20\d\d)\b/i);
  return m ? new Date(Date.UTC(+m[3], MONTHS[m[1].toLowerCase()], +m[2])).toISOString() : null;
};

const cleanScrapedMarkdown = (raw) => {
  if (!raw || typeof raw !== 'string') return '';

  let text = raw;

  // 1. Strip the huge header navigation tree (everything before the first # title)
  const firstHeaderIdx = text.search(/^#\s+/m);
  if (firstHeaderIdx !== -1) {
    text = text.slice(firstHeaderIdx);
  } else {
    // Fallback: remove lines that are pure top-level navigation links
    text = text.replace(/^(\s*[-*]\s+\[[^\]]+\]\([^)]+\)\s*)+/m, '');
  }

  // 2. Remove footer boilerplate (e.g., [Back to Top], tracker words like "Qualified")
  text = text.replace(/\[Back to Top\]\([^)]+\)/gi, '');
  text = text.replace(/\b(Qualified|Accept all cookies|Cookie Settings|Privacy Policy)\b/gi, '');

  // 3. Remove markdown images: ![alt](url)
  text = text.replace(/!\[.*?\]\(.*?\)/g, '');

  // 4. Flatten markdown links: convert [Anchor](url) to just Anchor
  //    (Ignore self-referential /# links completely)
  text = text.replace(/\[([^\]]+)\]\([^)]*#\)/g, '$1');
  text = text.replace(/\[([^\]]+)\]\([^)]+\)/g, '$1');

  // 5. Strip any raw leftover HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

  // 6. Clean up multiple empty lines and excessive spaces
  text = text
    .split('\n')
    .map(line => line.trim())
    .filter(line => line.length > 0)
    .join('\n');

  return text.trim();
};

// ===== DEDUPE MEMORY (shared across ALL batches and competitors of this run) =====
// This node runs once per batch of 5 pages, so a plain Set would only dedupe inside one batch.
// Workflow static data keeps the memory between batches; it resets automatically for a new run.
let store = null;
try {
  const sd = $getWorkflowStaticData('global');
  const execId = String(($execution && $execution.id) || '');
  const d = sd.pageDedupe;
  const stale = !d || d.execId !== execId || (Date.now() - (d.updatedAt || 0)) > RESET_AFTER_MS;
  if (stale) sd.pageDedupe = { execId, updatedAt: Date.now(), urls: [], hashes: [], docs: [] };
  store = sd.pageDedupe;
} catch (e) {}
if (!store) store = { urls: [], hashes: [], docs: [] }; // fallback: dedupe within this batch only

const seenUrls = new Set(store.urls);
const seenHashes = new Set(store.hashes);   // entries look like "company|contenthash"
const docs = store.docs;                    // entries look like { company, id, tokens: [...] }

// ===== COMPANY / LINK INFO =====
let currentCompany = null;
try { currentCompany = $('Loop Over Competitors').first().json.company; } catch (e) {}
if (!currentCompany) {
  try { currentCompany = $('Filter Useful Links').first().json.company; } catch (e) {}
}

// Link info (company, section, category, extract_focus, url_date, time_sensitive) from the batch just scraped.
// Matched by URL, so every page gets the right company even across loop runs.
const linkInfo = {};
try {
  for (const it of $('Wait').all()) {
    const j = it.json || {};
    if (j.url) linkInfo[norm(j.url)] = j;
  }
} catch (e) {}

// ===== MAIN LOOP =====
const out = [];
const stats = { in: 0, empty_or_short: 0, old: 0, dup_url: 0, dup_exact: 0, dup_near: 0, kept: 0 };
const cutoff = Date.now() - MAX_AGE_DAYS * 86400000;

for (const item of $input.all()) {
  stats.in++;
  const json = item.json || {};

  // Handle Firecrawl standard response shapes
  const scrapeData = json.data || json;
  const rawMarkdown = scrapeData.markdown || scrapeData.content || '';
  const metadata = scrapeData.metadata || {};

  // Keep the original URL (case matters in some URLs); use a normalized key only for matching and dedupe
  const requestedUrl = String(metadata.sourceURL || json.url || metadata.url || '').replace(/\/+$/, '');
  const targetUrl = String(metadata.url || metadata.sourceURL || json.url || '').replace(/\/+$/, '');
  const urlKey = norm(targetUrl);
  const requestedKey = norm(requestedUrl);

  // ---- Layer 1: URL dedupe (checks both the requested URL and the final URL after redirects) ----
  if ((urlKey && seenUrls.has(urlKey)) || (requestedKey && seenUrls.has(requestedKey))) { stats.dup_url++; continue; }
  if (urlKey) seenUrls.add(urlKey);
  if (requestedKey) seenUrls.add(requestedKey);

  // Clean the content
  const cleaned = cleanScrapedMarkdown(rawMarkdown);
  if (!cleaned || cleaned.length < MIN_BODY_LENGTH) { stats.empty_or_short++; continue; }

  // Link info and company
  const info = linkInfo[requestedKey] || linkInfo[urlKey] || {};
  const company = info.company || json.company || currentCompany || metadata.ogSiteName || '';

  // News (time-sensitive) vs evergreen. Falls back to the URL path if link info is missing.
  let pathOnly = '';
  try { pathOnly = new URL(targetUrl).pathname.toLowerCase(); } catch (e) {}
  const isTimeSensitive = typeof info.time_sensitive === 'boolean' ? info.time_sensitive : TIME_SENSITIVE_PATH.test(pathOnly);

  // Publish date: metadata first, then a date written in the page text (time-sensitive pages only)
  let publishedAt = toIso(metadata.publishedTime || metadata['article:published_time']);
  if (!publishedAt && isTimeSensitive) publishedAt = dateFromText(cleaned.slice(0, 800));
  const lastModified = toIso(metadata.modifiedTime);

  // Drop old time-sensitive pages (evergreen pages are never dropped for age)
  if (isTimeSensitive && publishedAt && Date.parse(publishedAt) < cutoff) { stats.old++; continue; }

  // Truncate to the maximum LLM-friendly character budget
  const finalContent = cleaned.length > MAX_CHAR_LENGTH
    ? cleaned.slice(0, MAX_CHAR_LENGTH) + '\n\n[...Content truncated for LLM]'
    : cleaned;

  // ---- Layer 2: exact content duplicate (same full text under a different URL), per company ----
  const contentHash = String(cyrb53(fingerprintText(cleaned)));
  const hashKey = company + '|' + contentHash;
  if (seenHashes.has(hashKey)) { stats.dup_exact++; continue; }

  // ---- Layer 3: near-duplicate (e.g. same article at /blog/x and /news/x with small differences) ----
  const tokens = tokensOf(finalContent);
  let nearDup = false;
  for (const d of docs) {
    if (d.company !== company) continue;
    if (jaccard(tokens, d.tokens) >= NEAR_DUP_THRESHOLD) { nearDup = true; break; }
  }
  if (nearDup) { stats.dup_near++; continue; }

  // Passed every check: register it so later batches can't repeat it
  seenHashes.add(hashKey);
  const id = 'website_' + cyrb53(urlKey);
  docs.push({ company, id, tokens });

  out.push({
    json: {
      status: 'ok',
      id,
      company,
      source: 'website',
      section: info.section || null,
      category: info.category || null,
      extract_focus: info.extract_focus || null,
      content_type: isTimeSensitive ? 'news' : 'evergreen',
      content_hash: contentHash,
      title: metadata.title || metadata.ogTitle || json.title || '',
      url: targetUrl,
      published_at: isTimeSensitive ? publishedAt : null,
      last_modified: lastModified,
      date_known: isTimeSensitive ? !!publishedAt : false,
      url_date: info.url_date || null,
      description: metadata.description || metadata.ogDescription || '',
      text: finalContent,
      cleaned_content: finalContent,
      char_count: finalContent.length,
      image_urls: [],
      image_analysis: null,
      collected_at: new Date().toISOString(),
      filter_status: 'keep'
    }
  });
  stats.kept++;
}

// Save dedupe memory for the next batch
store.urls = Array.from(seenUrls);
store.hashes = Array.from(seenHashes);
store.updatedAt = Date.now();

console.log('clean the scraped results:', JSON.stringify(stats));

return out;

// 1. Helper to safely extract remainingCredits whether nested in .data or at the root
const extractCredits = (nodeName) => {
  try {
    const item = $(nodeName).first()?.json || {};
    // Checks data.remainingCredits, remainingCredits, and snake_case variations
    const credits = 
      item.data?.remainingCredits ??
      item.remainingCredits ??
      item.data?.remaining_credits ??
      item.remaining_credits ??
      null;
    return typeof credits === 'number' ? credits : null;
  } catch (e) {
    return null;
  }
};

const startCredits = extractCredits('Firecrawl Usage Start');
const endCredits = extractCredits('Firecrawl Usage End');

let firecrawlCreditsUsed = 0;

if (startCredits !== null && endCredits !== null) {
  // 11085 - 11029 = 56
  firecrawlCreditsUsed = Math.max(0, startCredits - endCredits);
} else {
  // Deterministic fallback: 1 credit per map + 1 credit per scraped page
  try {
    const mapsCount = $('Map Competitor Website').all().length;
    const scrapesCount = $('scrape the urls').all().length;
    firecrawlCreditsUsed = mapsCount + scrapesCount;
  } catch (e) {
    firecrawlCreditsUsed = 0;
  }
}

// 2. Aggregate Gemini token usage across ALL loop runs
let totalPromptTokens = 0;
let totalCandidateTokens = 0;
let totalTokens = 0;
let totalImagesProcessed = 0;

let runIdx = 0;
while (true) {
  let batch;
  try {
    batch = $('Gemini Token Usage').all(0, runIdx);
  } catch (e) {
    break; // no more runs (or the node never ran)
  }
  if (!batch || !batch.length) break;
  for (const item of batch) {
    const u = item.json?._usage || {};
    totalPromptTokens += u.prompt_tokens || 0;
    totalCandidateTokens += u.candidate_tokens || 0;
    totalTokens += u.total_tokens || 0;
    totalImagesProcessed++;
  }
  runIdx++;
}

// 3. Return clean telemetry metric object
return [{
  json: {
    run_timestamp: new Date().toISOString(),
    firecrawl_start_credits: startCredits ?? 'N/A',
    firecrawl_end_credits: endCredits ?? 'N/A',
    firecrawl_credits_used: firecrawlCreditsUsed, // Evaluates to 56
    gemini_prompt_tokens: totalPromptTokens,
    gemini_candidate_tokens: totalCandidateTokens,
    gemini_total_tokens: totalTokens,
    gemini_images_analyzed: totalImagesProcessed,
    estimated_gemini_cost_usd: (totalPromptTokens * 0.000000075) + (totalCandidateTokens * 0.0000003)
  }
}];

// Place this Code node as the very first node on the 'done' output of Loop Over Competitors
const allPhase1Items = [];
let runIndex = 0;

while (true) {
  try {
    const items = $('Ready for AI Analysis (next)').all(0, runIndex);
    if (!items || !items.length) break;
    for (const item of items) {
      if (item.json && item.json.id) {
        allPhase1Items.push(item);
      }
    }
    runIndex++;
  } catch (e) {
    break;
  }
}

return allPhase1Items;

// Clean text helper
const cleanText = (t) => {
  if (!t || typeof t !== 'string') return '';
  return t
    .replace(/^based on the provided image,?\s*(here is a factual description:?)?/i, '')
    .replace(/^\s*[\*\-]\s+/gm, '')
    .replace(/[*_#`"]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{2,}/g, ' ')
    .trim();
};

// Retrieve posts that entered the Gemini branch
const originalPosts = $('Has Images?').all().map(i => i.json).filter(p => Array.isArray(p.image_urls) && p.image_urls.length > 0);
const geminiOutputs = $input.all();

let totalPromptTokens = 0;
let totalCandidateTokens = 0;
let totalTokens = 0;

const logRecords = [];
const out = [];

for (let i = 0; i < originalPosts.length; i++) {
  const post = originalPosts[i];
  const geminiItem = geminiOutputs[i]?.json || {};

  // 1. Extract token usage metadata from Gemini raw response
  const usage = geminiItem.usageMetadata || {};
  const promptTokens = usage.promptTokenCount || 0;
  const candidateTokens = usage.candidatesTokenCount || 0;
  const itemTotalTokens = usage.totalTokenCount || (promptTokens + candidateTokens);

  totalPromptTokens += promptTokens;
  totalCandidateTokens += candidateTokens;
  totalTokens += itemTotalTokens;

  // 2. Extract and sanitize output
  const rawAnalysis = 
    geminiItem.content?.parts?.[0]?.text || 
    geminiItem.text || 
    '';

  let cleaned = cleanText(rawAnalysis);
  if (!cleaned || cleaned.toUpperCase().startsWith('NONE') || cleaned.length < 15) {
    cleaned = null;
  }

  // 3. Record log item
  logRecords.push({
    post_id: post.id,
    company: post.company,
    prompt_tokens: promptTokens,
    candidate_tokens: candidateTokens,
    total_tokens: itemTotalTokens,
    has_substance: cleaned !== null
  });

  // 4. Output post schema enriched with usage telemetry
  out.push({
    json: {
      ...post,
      image_analysis: cleaned,
      _usage: {
        prompt_tokens: promptTokens,
        candidate_tokens: candidateTokens,
        total_tokens: itemTotalTokens,
        model: 'gemini-3.5-flash-lite'
      }
    }
  });
}

// ===== CONSOLE OBSERVABILITY LOGGING =====
console.log('================ GEMINI VISION OBSERVABILITY LOG ================');
console.table(logRecords);
console.log(`Total Requests: ${logRecords.length}`);
console.log(`Prompt Tokens:   ${totalPromptTokens}`);
console.log(`Response Tokens: ${totalCandidateTokens}`);
console.log(`Total Tokens:    ${totalTokens}`);
console.log('=================================================================');

return out;

