const existing = new Map();
for (const it of $input.all()) {
  const r = it.json;
  if (r.id) existing.set(String(r.id), String(r.content_hash || ''));
}

const out = [];
for (const it of $('Final output for AI analysis').all()) {
  const j = it.json;
  const prevHash = existing.get(String(j.id));

  if (prevHash === undefined) { out.push(it); continue; }          // brand new item

  // Evergreen page whose content changed since last run: re-queue it
  if (j.source === 'website' && j.content_hash && prevHash &&
      prevHash !== String(j.content_hash)) out.push(it);
  // otherwise it was already stored, so skip it and keep its status
}
return out;

const t = $input.first().json;
const items = $('Final output for AI analysis').all().map(i => i.json);
return [{ json: {
  run_id: 'p1_' + $execution.id,
  phase: 1,
  run_at: t.run_timestamp,
  status: 'ok',
  items_collected: items.length,
  linkedin_items: items.filter(i => i.source === 'linkedin').length,
  website_items: items.filter(i => i.source === 'website').length,
  firecrawl_credits: t.firecrawl_credits_used,
  gemini_images_analyzed: t.gemini_images_analyzed,
  gemini_prompt_tokens: t.gemini_prompt_tokens,
  gemini_output_tokens: t.gemini_candidate_tokens,
  gemini_usd: Math.round(t.estimated_gemini_cost_usd * 1e6) / 1e6
}}];
